+  let record: string[] = [];
+  let field = '';
+  let inQuotes = false;
+
+  const endRecord = (): void => {
+    record.push(field);
+    field = '';
+    if (record.some((c) => c.trim() !== '')) records.push(record); // skip blank lines
+    record = [];
+  };
+
+  for (let i = 0; i < text.length; i++) {
+    const ch = text[i];
+    if (inQuotes) {
+      if (ch === '"') {
+        if (text[i + 1] === '"') {
+          field += '"';
+          i++;
+        } else {
+          inQuotes = false;
+        }
+      } else {
+        field += ch;
+      }
+    } else if (ch === '"') {
+      inQuotes = true;
+    } else if (ch === ',') {
+      record.push(field);
+      field = '';
+    } else if (ch === '\n') {
+      endRecord();
+    } else if (ch === '\r') {
+      // swallow; the following \n (if any) ends the record
+      if (text[i + 1] !== '\n') endRecord();
+    } else {
+      field += ch;
+    }
+  }
+  if (field !== '' || record.length > 0) endRecord();
+  return records;
+}
+
+/** Same contract as parseLegacyCsv, but handles quoted fields. */
+export function parseImportCsv(text: string): LegacyRow[] {
+  const records = parseCsvRecords(text);
+  if (records.length === 0) return [];
+
+  const header = records[0].map((h) => h.trim().toLowerCase());
+  return records.slice(1).map((cells) => {
+    const get = (name: string): string => (cells[header.indexOf(name)] ?? '').trim();
+    const phone = get('phone');
+    return {
+      tracking_number: get('tracking'),
+      carrier: mapLegacyCarrier(get('carrier')),
+      service_level: get('service') || 'standard',
+      recipient: {
+        name: get('name'),
+        street: get('street'),
+        zip: get('zip'),
+        city: get('city'),
+        country: get('country') || 'AT',
+        ...(phone ? { phone } : {}),
+      },
+    };
+  });
+}
